package br.com.sistemacardapio.catalogo;import java.math.BigDecimal;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import br.com.sistemacardapio.tenant.TenantContext;
@Service public class ProdutoVariacaoService{private final ProdutoVariacaoRepository repo;private final ProdutoRepository produtos;private final TenantContext tenant;public ProdutoVariacaoService(ProdutoVariacaoRepository r,ProdutoRepository p,TenantContext t){repo=r;produtos=p;tenant=t;}@Transactional(readOnly=true)public List<Response>listar(UUID p){UUID e=tenant.empresaIdObrigatoria();produto(p,e);return repo.findAllByProdutoIdAndEmpresaIdOrderByOrdemAsc(p,e).stream().map(Response::from).toList();}@Transactional public Response criar(UUID p,Request r){UUID e=tenant.empresaIdObrigatoria();return Response.from(repo.save(new ProdutoVariacao(produto(p,e),r.nome(),r.preco(),r.ordem())));}@Transactional public Response atualizar(UUID p,UUID id,Request r){UUID e=tenant.empresaIdObrigatoria();ProdutoVariacao v=repo.findByIdAndProdutoIdAndEmpresaId(id,p,e).orElseThrow(()->new IllegalStateException("Variação não encontrada"));v.atualizar(r.nome(),r.preco(),r.ordem(),r.ativa());return Response.from(v);}private Produto produto(UUID p,UUID e){return produtos.findByIdAndEmpresaId(p,e).orElseThrow(()->new IllegalStateException("Produto não encontrado"));}public record Request(@jakarta.validation.constraints.NotBlank String nome,@jakarta.validation.constraints.NotNull @jakarta.validation.constraints.PositiveOrZero BigDecimal preco,@jakarta.validation.constraints.PositiveOrZero int ordem,boolean ativa){}public record Response(UUID id,String nome,BigDecimal preco,int ordem,boolean ativa){static Response from(ProdutoVariacao v){return new Response(v.getId(),v.getNome(),v.getPreco(),v.getOrdem(),v.isAtiva());}}}
